GLSL_SOURCE.fieldStrength_frag="#version 100\r\n#extension GL_OES_standard_derivatives : enable\r\n#define COLOR_COUNT 16\r\n\r\nprecision highp float;\r\nprecision highp int;\r\n\r\nuniform mat4 matField;\r\n\r\nuniform sampler2D GainMap;\r\nuniform vec3 FieldRelativeNode;\r\nuniform float FieldRadius;\r\nuniform float PlaneCenter;\r\nuniform float ExtendAngle;\r\nuniform float Opacity;\r\nuniform vec4 ColorArray[COLOR_COUNT];\r\nuniform float StrengthArray[COLOR_COUNT];\r\n\r\nuniform float EffectiveRadiatedPower;\r\nuniform float Frequency;\r\nuniform float EccentricitySquared;\r\n\r\nuniform bool UseViewShed;\r\nuniform vec3 Offset;\r\nuniform vec4 Boundary;\r\nuniform sampler2D Mask;\r\n\r\nvarying vec3 v_pos;\r\n\r\nfloat log10(float value){\r\n\treturn log(value)/log(10.0);\r\n}\r\n\r\nfloat getFieldValue(float distanceToCenter, float gain) {\r\n\tfloat fspl = 20.0 * log10(distanceToCenter) + 20.0 * log10(Frequency) + 32.45;\r\n\treturn EffectiveRadiatedPower - fspl + gain;\r\n}\r\n\r\nfloat getLine(float value){\r\n\tfloat grid = abs(fract(value - 0.5) - 0.5) / fwidth(value);\r\n\treturn 1.0 - min(grid, 1.0);\r\n}\r\n\r\nfloat getBoundLine(float distanceToFieldCenter, float radius){\r\n\tfloat boundLine = getLine(distanceToFieldCenter / radius);\r\n\tboundLine = mix(boundLine,0.0,abs(distanceToFieldCenter - radius) / radius * 2.0);\r\n\treturn boundLine;\r\n}\r\n\r\nfloat getGain(float direction){\r\n\treturn texture2D(GainMap, vec2(abs(direction) / 180.0 ,0.5)).r;\r\n}\r\n\r\nfloat getDirection(vec3 relativePos, float faceAngle){\r\n\tvec2 relativeDirection = normalize(relativePos.xy);\r\n\tvec2 faceDirection = vec2(sin(faceAngle),cos(faceAngle));\r\n\treturn degrees(acos(clamp(dot(relativeDirection,faceDirection),-1.0,1.0)));\r\n}\r\n\r\nvec4 getFieldColor(float fieldResult){\r\n\tvec4 resultColor = ColorArray[0];\r\n\tfor(int i = 0;i < COLOR_COUNT - 1;i++){\r\n\t\tif(fieldResult>StrengthArray[i]){\r\n\t\t\tfloat stepNow = StrengthArray[i];\r\n\t\t\tfloat stepNext = StrengthArray[i + 1];\r\n\t\t\tfloat stepGap = stepNext - stepNow;\r\n\t\t\tfloat fieldGap = fieldResult - stepNow;\r\n\t\t\tresultColor = mix(ColorArray[i],ColorArray[i + 1], fieldGap / stepGap);\r\n\t\t}\r\n\t}\r\n\treturn resultColor;\r\n}\r\n\r\nvec3 worldXYZToMap(vec3 worldXYZ){\r\n\t//ECEF to lng lat from JS code.\r\n\tconst float Radius = 6378137.0;\r\n\tfloat a1 = Radius * EccentricitySquared;\r\n\tfloat a2 = a1 * a1;\r\n\tfloat a3 = 0.5 * a1 * EccentricitySquared;\r\n\tfloat a4 = 2.5 * a2;\r\n\tfloat a5 = a1 + a3;\r\n\tfloat a6 = 1.0 - EccentricitySquared;\r\n\r\n\tfloat x = worldXYZ.x;\r\n\tfloat y = worldXYZ.y;\r\n\tfloat z = worldXYZ.z;\r\n\r\n\tfloat zp = abs(z);\r\n\tfloat w2 = x * x + y * y;\r\n\tfloat w = sqrt(w2);\r\n\tfloat r2 = w2 + z * z;\r\n\tfloat r = sqrt(r2);\r\n\r\n\tworldXYZ.x = atan(y, x);\r\n\r\n\tfloat s2 = z * z / r2;\r\n\tfloat c2 = w2 / r2;\r\n\tfloat u = a2 / r;\r\n\tfloat v = a3 - a4 / r;\r\n\r\n\tfloat s;\r\n\tfloat ss;\r\n\tfloat c;\r\n\r\n\tif (c2 > 0.3) {\r\n\t\ts = (zp / r) * (1.0 + c2 * (a1 + u + s2 * v) / r);\r\n\t\tworldXYZ.y = asin(s);\r\n\t\tss = s * s;\r\n\t\tc = sqrt(1.0 - ss);\r\n\t} else {\r\n\t\tc = (w / r) * (1.0 - s2 * (a5 - u - c2 * v) / r);\r\n\t\tworldXYZ.y = acos(c);\r\n\t\tss = 1.0 - c * c;\r\n\t\ts = sqrt(ss);\r\n\t}\r\n\r\n\tfloat g = 1.0 - EccentricitySquared * ss;\r\n\tfloat rg = Radius / sqrt(g);\r\n\tfloat rf = a6 * rg;\r\n\tu = w - rg * c;\r\n\tv = zp - rf * s;\r\n\tfloat f = c * u + s * v;\r\n\tfloat m = c * v - s * u;\r\n\tfloat p2 = m / (rf / g + f);\r\n\tworldXYZ.y = worldXYZ.y + p2;\r\n\tworldXYZ.z = f + m * p2 / 2.0;\r\n\tif (z < 0.0) \r\n\t\tworldXYZ.y *= -1.0;\r\n\r\n\tworldXYZ.x = degrees(worldXYZ.x);\r\n\tworldXYZ.y = degrees(worldXYZ.y);\r\n\treturn worldXYZ;\r\n}\r\n\r\nbool inRect(vec2 p,vec4 rect){\r\n\treturn (p.x>=rect.x && p.y>=rect.y && p.x <= rect.z && p.y <= rect.w);\r\n}\r\n\r\nvec2 mapToTp(vec2 p,vec4 rect){\r\n\tvec2 size = rect.zw - rect.xy;\r\n\treturn (p - rect.xy) / size;\r\n}\r\n\r\nvoid main(){\r\n\tvec3 map = worldXYZToMap(v_pos + Offset);\r\n\r\n\tvec3 relativePos = (matField * vec4(v_pos + FieldRelativeNode, 1.0)).xyz;\r\n\tfloat distanceToFieldCenter = length(relativePos);\r\n\tfloat direction = getDirection(relativePos,radians(PlaneCenter));\r\n\tfloat gain = getGain(direction);\r\n\tfloat boundLine = getBoundLine(distanceToFieldCenter, FieldRadius);\r\n\r\n\tif(boundLine< 0.5 && inRect(map.xy,Boundary) && UseViewShed){\r\n\t\tvec4 mask = texture2D(Mask,mapToTp(map.xy, Boundary));\r\n\t\tif (mask.g < 1.0) \r\n\t\t\tdiscard;\r\n\t}\r\n\t\r\n\tfloat fieldResult = getFieldValue(distanceToFieldCenter * 0.001, gain);\r\n\r\n\tgl_FragColor = vec4(1.0, 1.0, 1.0, 0.0);\r\n\r\n\tif(distanceToFieldCenter < FieldRadius && direction <= ExtendAngle * 0.5){\r\n\t\tgl_FragColor = getFieldColor(fieldResult);\r\n\t\tgl_FragColor.a *= Opacity;\r\n\t}\r\n\r\n\tgl_FragColor = mix(gl_FragColor,vec4(1.0),boundLine);\r\n}";
GLSL_SOURCE.fieldStrength_vert="#version 100\r\nprecision highp float;\r\nprecision highp int;\r\n\r\nuniform mat4 matWorldViewProj;\r\n\r\nattribute vec4 Input_p;\r\n\r\nvarying vec3 v_pos;\r\n\r\nvoid main(){\r\n\tv_pos = Input_p.xyz;\r\n\tgl_Position = matWorldViewProj * Input_p;\r\n}";GLSL_SOURCE.radar2DSurfaceShader_frag="#version 100\r\nprecision highp float;\r\nprecision highp int;\r\n\r\nuniform sampler2D Mask;\r\nuniform vec3 Offset;\r\nuniform vec4 Boundary;\r\nuniform vec4 ViewColor;\r\nuniform vec4 UnviewColor;\r\nuniform float EccentricitySquared;\r\n\r\nvarying vec3 v_pos;\r\n\r\nvec3 worldXYZToMap(vec3 worldXYZ){\r\n\t//ECEF to lng lat from JS code.\r\n\tconst float Radius = 6378137.0;\r\n\tfloat a1 = Radius * EccentricitySquared;\r\n\tfloat a2 = a1 * a1;\r\n\tfloat a3 = 0.5 * a1 * EccentricitySquared;\r\n\tfloat a4 = 2.5 * a2;\r\n\tfloat a5 = a1 + a3;\r\n\tfloat a6 = 1.0 - EccentricitySquared;\r\n\r\n\tfloat x = worldXYZ.x;\r\n\tfloat y = worldXYZ.y;\r\n\tfloat z = worldXYZ.z;\r\n\r\n\tfloat zp = abs(z);\r\n\tfloat w2 = x * x + y * y;\r\n\tfloat w = sqrt(w2);\r\n\tfloat r2 = w2 + z * z;\r\n\tfloat r = sqrt(r2);\r\n\r\n\tworldXYZ.x = atan(y, x);\r\n\r\n\tfloat s2 = z * z / r2;\r\n\tfloat c2 = w2 / r2;\r\n\tfloat u = a2 / r;\r\n\tfloat v = a3 - a4 / r;\r\n\r\n\tfloat s;\r\n\tfloat ss;\r\n\tfloat c;\r\n\r\n\tif (c2 > 0.3) {\r\n\t\ts = (zp / r) * (1.0 + c2 * (a1 + u + s2 * v) / r);\r\n\t\tworldXYZ.y = asin(s);\r\n\t\tss = s * s;\r\n\t\tc = sqrt(1.0 - ss);\r\n\t} else {\r\n\t\tc = (w / r) * (1.0 - s2 * (a5 - u - c2 * v) / r);\r\n\t\tworldXYZ.y = acos(c);\r\n\t\tss = 1.0 - c * c;\r\n\t\ts = sqrt(ss);\r\n\t}\r\n\r\n\tfloat g = 1.0 - EccentricitySquared * ss;\r\n\tfloat rg = Radius / sqrt(g);\r\n\tfloat rf = a6 * rg;\r\n\tu = w - rg * c;\r\n\tv = zp - rf * s;\r\n\tfloat f = c * u + s * v;\r\n\tfloat m = c * v - s * u;\r\n\tfloat p2 = m / (rf / g + f);\r\n\tworldXYZ.y = worldXYZ.y + p2;\r\n\tworldXYZ.z = f + m * p2 / 2.0;\r\n\tif (z < 0.0) \r\n\t\tworldXYZ.y *= -1.0;\r\n\r\n\tworldXYZ.x = degrees(worldXYZ.x);\r\n\tworldXYZ.y = degrees(worldXYZ.y);\r\n\treturn worldXYZ;\r\n}\r\n\r\nbool inRect(vec2 p,vec4 rect){\r\n\treturn (p.x>=rect.x && p.y>=rect.y && p.x <= rect.z && p.y <= rect.w);\r\n}\r\n\r\nvec2 mapToTp(vec2 p,vec4 rect){\r\n\tvec2 size = rect.zw - rect.xy;\r\n\treturn (p - rect.xy) / size;\r\n}\r\n\r\nvoid main(){\r\n\tvec3 map = worldXYZToMap(v_pos + Offset);\r\n\r\n\tif(inRect(map.xy,Boundary)){\r\n\t\tvec4 mask = texture2D(Mask,mapToTp(map.xy, Boundary));\r\n\t\tgl_FragColor = mix(UnviewColor,ViewColor,mask.g);\r\n\t\tgl_FragColor.a *= mask.a;\r\n\t}else{\r\n\t\tgl_FragColor = vec4(0.0,0.0,0.0,0.0);\r\n\t}\r\n}";
GLSL_SOURCE.radar2DSurfaceShader_vert="#version 100\r\nprecision highp float;\r\nprecision highp int;\r\n\r\nuniform mat4 matWorldViewProj;\r\n\r\nattribute vec4 Input_p;\r\nattribute vec2 Input_tp1;\r\n\r\nvarying vec3 v_pos;\r\nvarying vec2 v_tp;\r\n\r\nvoid main(){\r\n\tv_pos = Input_p.xyz;\r\n\tv_tp = Input_tp1;\r\n\tgl_Position = matWorldViewProj * Input_p;\r\n}";GLSL_SOURCE.radarAnime_frag="#version 100\r\nprecision highp float;\r\nprecision highp int;\r\n\r\n//Fragment Shader\r\nuniform vec4 SurfaceColor;\r\nuniform vec4 SurfaceScanColor;\r\nuniform vec2 ScanPower;\r\nuniform float ScanPosition;\r\nuniform vec2 LongitudeRange;\r\n\r\nvarying vec3 v_xyz;\r\nvarying vec3 v_xyzAhead;\r\n\r\nvec2 getDirection(float pos)\r\n{\r\n\tconst float PI = 3.1415926535897;\r\n\r\n\treturn vec2(cos(pos * PI * 2.0),sin(pos * PI * 2.0));\r\n}\r\n\r\nfloat getScanFactor()\r\n{\r\n\tvec2 scanDirection = normalize(getDirection(mix(LongitudeRange.x,LongitudeRange.y,ScanPosition)));\r\n\tvec2 faceDirection = normalize(v_xyz.xy);\r\n\tvec2 faceDirectionAhead = normalize(v_xyzAhead.xy);\r\n\tfloat scanFactor = max(dot(scanDirection,faceDirection),0.0);\r\n\r\n\treturn dot(scanDirection,faceDirectionAhead) < 0.0 ? pow(scanFactor,ScanPower.x) : pow(scanFactor,ScanPower.y);\r\n}\r\n\r\nvoid main()\r\n{\r\n\tgl_FragColor = mix(SurfaceColor, SurfaceScanColor, getScanFactor());\r\n}";
GLSL_SOURCE.radarAnime_vert="#version 100\r\nprecision highp float;\r\nprecision highp int;\r\n//Vertex Shader\r\n\r\n//Matrix\r\nuniform mat4 matWorldViewProj;\r\nuniform vec2 RadiusRange;\r\nuniform vec2 LongitudeRange;\r\nuniform vec2 LatitudeRange;\r\n\r\nattribute vec4 Input_p;\r\n\r\nvarying vec3 v_xyz;\r\nvarying vec3 v_xyzAhead;\r\n\r\nvec3 clampPos(vec3 pos)\r\n{\r\n\treturn vec3(\r\n\t\tmix(LongitudeRange.x,LongitudeRange.y,Input_p.x),\r\n\t\tmix(LatitudeRange.x,LatitudeRange.y,Input_p.y),\r\n\t\tmix(RadiusRange.x,RadiusRange.y,Input_p.z)\r\n\t);\r\n}\r\n\r\nvec3 toSpherical(vec3 pos)\r\n{\r\n\tconst float PI = 3.1415926535897;\r\n\r\n\treturn vec3(\r\n\t\tsin(pos.y * PI) * cos(pos.x * PI * 2.0),\r\n\t\tsin(pos.y * PI) * sin(pos.x * PI * 2.0),\r\n\t\tcos(pos.y * PI)\r\n\t) * pos.z;\r\n}\r\n\r\nvoid main()\r\n{\r\n\tvec3 pos = clampPos(Input_p.xyz);\r\n\tv_xyz = toSpherical(pos);\r\n\tv_xyzAhead = toSpherical(pos + vec3(0.25,0.0,0.0));\r\n\tgl_Position = matWorldViewProj * vec4(toSpherical(pos),1.0);\r\n}\r\n";
GLSL_SOURCE.symbolPoint_frag="#version 100\r\nprecision highp float;\r\nprecision mediump int;\r\n\r\n//Fragment Shader\r\n\r\nuniform sampler2D BaseSampler;\r\n\r\nvoid main()\r\n{\r\n\tgl_FragColor = texture2D(BaseSampler, gl_PointCoord);\r\n\tif(gl_FragColor.a < 0.1)\r\n\t\tdiscard;\r\n}";GLSL_SOURCE.symbolPoint_vert="#version 100\r\nprecision highp float;\r\nprecision mediump int;\r\n//Vertex Shader\r\n\r\n//Matrix\r\nuniform highp mat4 matViewProj;\r\nuniform highp vec3 Offset;\r\nuniform highp float Size;\r\n\r\nattribute highp vec4 Input_p;\r\n\r\nvoid main()\r\n{\r\n\tgl_PointSize = Size;\r\n\tgl_Position = matViewProj*vec4(Input_p.xyz + Offset,1);\r\n}\r\n";
GLSL_SOURCE.ParticleSystemShader_frag="#version 100\r\nprecision highp float;\r\nprecision highp int;\r\n\r\nuniform sampler2D Sampler;\r\nuniform highp vec2 ColRow;\r\nuniform bool IsLineStripParticle;\r\n\r\nvarying highp float v_AtlasLocation;\r\nvarying highp vec2 v_Coord;\r\nvarying highp vec4 v_Frame;\r\nvarying highp float v_Weights;\r\n\r\nvoid main(){\r\n\tif(IsLineStripParticle){\r\n\t\thighp vec2 scale = vec2(1.0 / ColRow.x, 1.0 / ColRow.y);\r\n\t\thighp float col, row;\r\n\t\tcol = v_AtlasLocation - (4.0 * floor(v_AtlasLocation / 4.0 + 0.1));\r\n\t\trow = floor(v_AtlasLocation / 4.0 + 0.1);\r\n\t\thighp vec2 deviation = scale * vec2(col, row);\r\n\t\thighp vec2 offset = v_Coord * scale + deviation;\r\n\t\tgl_FragColor = texture2D(Sampler, offset);\r\n\t}\r\n\telse{\r\n\t\thighp vec2 scale = vec2(1.0 / ColRow.x, 1.0 / ColRow.y);\r\n\t\thighp float col, row;\r\n\t\tcol = v_AtlasLocation - (4.0 * floor(v_AtlasLocation / 4.0 + 0.1));\r\n\t\trow = floor(v_AtlasLocation / 4.0 + 0.1);\r\n\t\thighp vec2 deviation = scale * vec2(col, row);\r\n\r\n\t\t// v_Frame.x: frameMaxCol\r\n\t\t// v_Frame.y: frameMaxRow\r\n\t\t// v_Frame.z: frameAmount\r\n\t\t// v_Frame.w: frameNow\r\n\t\thighp vec2 frameScale = vec2(1.0 / v_Frame.x, 1.0 / v_Frame.y);\r\n\r\n\t\thighp float\tframe = floor(v_Frame.w + 0.5);\r\n\t\thighp float\tnextFrame = floor(v_Frame.w + 0.5) + 1.0;\r\n\t\tif(frame >= v_Frame.z - 1.0){\r\n\t\t\tframe = v_Frame.z - 1.0;\r\n\t\t\tnextFrame = v_Frame.z - 1.0;\r\n\t\t}\r\n\r\n\t\thighp float frameCol, frameRow, frameNextCol, frameNextRow;\r\n\t\tframeCol = frame - (v_Frame.x * floor(frame / v_Frame.x + 0.005));\r\n\t\tframeRow = floor(frame / v_Frame.x + 0.005);\r\n\r\n\t\tframeNextCol = nextFrame - (v_Frame.x * floor(nextFrame / v_Frame.x + 0.005));\r\n\t\tframeNextRow = floor(nextFrame / v_Frame.x + 0.005);\r\n\r\n\t\thighp vec2 frameDeviation = scale * frameScale * vec2(frameCol, frameRow);\r\n\t\thighp vec2 frameNextDeviation = scale * frameScale * vec2(frameNextCol, frameNextRow);\r\n\r\n\t\thighp vec2 frameOffset = v_Coord * scale * frameScale + frameDeviation + deviation;\r\n\t\thighp vec2 frameNextOffset = v_Coord * scale * frameScale + frameNextDeviation + deviation;\r\n\r\n\t\thighp vec4 texture0 = texture2D(Sampler, frameOffset);\r\n\t\thighp vec4 texture1 = texture2D(Sampler, frameNextOffset);\r\n\r\n\t\tgl_FragColor = mix(texture0, texture1, floor(v_Weights + 0.005) / 100.0);\r\n\t}\r\n}\r\n";
GLSL_SOURCE.ParticleSystemShader_vert="#version 100\r\nprecision highp float;\r\nprecision highp int;\r\n\r\nattribute highp vec2 Input_Billboard;\r\nattribute highp vec2 Input_Coord;\r\n\r\nattribute highp float Input_AtlasLocation;\r\nattribute highp float Input_Width;\r\nattribute highp float Input_Height;\r\nattribute highp float Input_Degree;\r\nattribute highp vec4 Input_Frame;\r\nattribute highp vec3 Input_Position0;\r\nattribute highp vec3 Input_Position1;\r\nattribute highp float Input_Weights;\r\n\r\nuniform highp mat4 matWorldViewProj;\r\nuniform highp mat4 matView;\r\nuniform bool IsLineStripParticle;\r\n\r\nvarying highp float v_AtlasLocation;\r\nvarying highp vec4 v_Frame;\r\nvarying highp vec2 v_Coord;\r\nvarying highp float v_Weights;\r\n\r\nvoid main(){\r\n\tif(IsLineStripParticle){\r\n\t\thighp vec3 facing = vec3(matView[0][2], matView[1][2], matView[2][2]);\r\n\t\tif(Input_Billboard.y > 0.0){\r\n\t\t\thighp vec3 direction = Input_Position1 - Input_Position0;\r\n\t\t\thighp vec3 crossDirection = normalize(cross(Input_Position0, direction));\r\n\t\t\tif(Input_Billboard.x > 0.0){\r\n\t\t\t\tgl_Position = matWorldViewProj * vec4(Input_Position0 - crossDirection * Input_Width, 1.0);\r\n\t\t\t}\r\n\t\t\telse{\r\n\t\t\t\tgl_Position = matWorldViewProj * vec4(Input_Position0 + crossDirection * Input_Width, 1.0);\r\n\t\t\t}\r\n\t\t}\r\n\t\telse{\r\n\t\t\thighp vec3 direction = Input_Position1 - Input_Position0;\r\n\t\t\thighp vec3 crossDirection = normalize(cross(Input_Position1, direction));\r\n\t\t\tif(Input_Billboard.x > 0.0){\r\n\t\t\t\tgl_Position = matWorldViewProj * vec4(Input_Position1 - crossDirection * Input_Width, 1.0);\r\n\t\t\t}\r\n\t\t\telse{\r\n\t\t\t\tgl_Position = matWorldViewProj * vec4(Input_Position1 + crossDirection * Input_Width, 1.0);\r\n\t\t\t}\t\t\r\n\t\t}\r\n\r\n\t\tv_Coord = Input_Coord;\r\n\t\tv_AtlasLocation = Input_AtlasLocation;\r\n\t}\r\n\telse{\r\n\t\tfloat rad = radians(Input_Degree);\r\n\t\t\r\n\t\thighp vec2 billboard;\r\n\t\tbillboard.x = Input_Billboard.x * Input_Width;\r\n\t\tbillboard.y = Input_Billboard.y * Input_Height;\r\n\r\n\t\thighp vec2 rotateBillboard;\r\n\t\trotateBillboard.x = billboard.x * cos(rad) - billboard.y * sin(rad);\r\n\t\trotateBillboard.y = billboard.x * sin(rad) + billboard.y * cos(rad);\r\n\r\n\t\thighp vec3 right = vec3(matView[0][0], matView[1][0], matView[2][0]);\r\n\t\thighp vec3 up = vec3(matView[0][1], matView[1][1], matView[2][1]);\r\n\t\thighp vec3 billboardVector =  right * rotateBillboard.x + up * rotateBillboard.y;\r\n\t\tgl_Position = matWorldViewProj * vec4(Input_Position0.xyz + billboardVector, 1.0);\r\n\r\n\t\tv_AtlasLocation = Input_AtlasLocation;\r\n\t\tv_Coord = Input_Coord;\r\n\t\tv_Frame = Input_Frame;\r\n\t\tv_Weights = Input_Weights;\r\n\t}\r\n}";
GLSL_SOURCE.skyline_frag="#version 100\r\nprecision highp float;\r\nprecision highp int;\r\n\r\nuniform sampler2D DepthMap;\r\nuniform int ScreenWidth;\r\nuniform int ScreenHeight;\r\nuniform float LineWidth;\r\nuniform vec4 LineColor;\r\n\r\n\r\nfloat unpackFloatFromVec4i(const vec4 value)\r\n{\r\n\tconst vec4 bitSh = vec4(1.0 / (255.0 * 255.0 * 255.0), 1.0 / (255.0 * 255.0), 1.0 / 255.0, 1.0);\r\n\treturn(dot(value, bitSh));\r\n}\r\n\r\nvoid main(){\r\n\tvec2 tp = vec2(gl_FragCoord.x/float(ScreenWidth),gl_FragCoord.y/float(ScreenHeight));\r\n\r\n\tfloat depth = unpackFloatFromVec4i(texture2D(DepthMap, tp));\r\n\tvec2 offset[8];\r\n\toffset[0] = vec2(-1.0, -1.0);\r\n\toffset[1] = vec2(0.0, -1.0);\r\n\toffset[2] = vec2(1.0, -1.0);\r\n\toffset[3] = vec2(1.0, 0.0);\r\n\toffset[4] = vec2(1.0, 1.0);\r\n\toffset[5] = vec2(0.0, 1.0);\r\n\toffset[6] = vec2(-1.0, 1.0);\r\n\toffset[7] = vec2(-1.0, 0.0);\r\n\r\nvec2 pixelSize = vec2(1.0 / float(ScreenWidth), 1.0 / float(ScreenHeight));\r\n\tfloat sum = 0.0;\r\n\tfor(int i = 0; i < 8; i++)\r\n\t{\r\n\t\tvec2 samplerTp = tp + pixelSize * offset[i] * LineWidth;\r\n\t\tsum += unpackFloatFromVec4i(texture2D(DepthMap, samplerTp));\r\n\t}\r\n\r\n\tif (depth == 0.0 && sum > 0.0) {\r\n\t\tgl_FragColor = vec4(LineColor);\r\n\t}\r\n\r\n\t//gl_FragColor = vec4(depth, sum, 0.0, 1.0);\r\n}\r\n";
GLSL_SOURCE.skyline_vert="#version 100\r\nprecision highp float;\r\nprecision highp int;\r\n\r\nattribute highp vec4 Input_p;\r\n\r\nvoid main(){\r\n\tgl_Position = vec4(Input_p.xy * 2.0 - 1.0, 0.0, 1.0);\r\n}";GLSL_SOURCE.imageDistortion_frag='#version 100\r\nprecision highp float;\r\nprecision highp int;\r\n\r\nuniform sampler2D ImageSource;\r\nuniform bool EnableDistort;\r\nuniform bool EnableUndistort;\r\n//\u76f8\u6a5f\u53c3\u6578\r\nuniform float CameraWidth;\r\nuniform float CameraHeight;\r\nuniform float CameraIntrinsicMatrix[9];\t\t//\u5167\u53c33*3\u77e9\u9663\r\nuniform float CameraDistortionCoefficient[5];\t//\u7578\u8b8a\u53c3\u6578\r\nuniform int ScreenWidth;\r\nuniform int ScreenHeight;\r\n\r\nvec2 distort(vec2 pt) {\r\n\tfloat fx = CameraIntrinsicMatrix[0];\r\n\tfloat fy = CameraIntrinsicMatrix[4];\r\n\tfloat ux = CameraIntrinsicMatrix[2];\r\n\tfloat uy = CameraIntrinsicMatrix[5];\r\n\r\n\tvec2 point = vec2 ((pt.x - ux) / fx, (pt.y - uy) / fy);\r\n\r\n\tfloat k1 = CameraDistortionCoefficient[0];\r\n\tfloat k2 = CameraDistortionCoefficient[1];\r\n\tfloat p1 = CameraDistortionCoefficient[2];\r\n\tfloat p2 = CameraDistortionCoefficient[3];\r\n\tfloat k3 = CameraDistortionCoefficient[4];\r\n\t//BOOST_FOREACH(const cv::Point2d &p, src) \r\n\r\n\tvec2 p = point;\r\n\tfloat x = p.x;\r\n\tfloat y = p.y;\r\n\tfloat xCorrected, yCorrected;\r\n\t//Step 1 : correct distorsion \r\n\t{\r\n\t\tfloat r2 = x * x + y * y;\r\n\t\t//radial distorsion \r\n\t\txCorrected = x * (1.0 + k1 * r2 + k2 * r2 * r2 + k3 * r2 * r2 * r2);\r\n\t\tyCorrected = y * (1.0 + k1 * r2 + k2 * r2 * r2 + k3 * r2 * r2 * r2);\r\n\r\n\t\t//tangential distorsion \r\n\t\t//The "Learning OpenCV" book is wrong here !!! \r\n\t\t//False equations from the "Learning OpenCv" book \r\n\t\t//xCorrected = xCorrected + (2. * p1 * y + p2 * (r2 + 2. * x * x)); \r\n\t\t//yCorrected = yCorrected + (p1 * (r2 + 2. * y * y) + 2. * p2 * x); \r\n\t\t//Correct formulae found at : http://www.vision.caltech.edu/bouguetj/calib_doc/htmls/parameters.html \r\n\t\txCorrected = xCorrected + (2.0 * p1 * x * y + p2 * (r2 + 2.0 * x * x));\r\n\t\tyCorrected = yCorrected + (p1 * (r2 + 2.0 * y * y) + 2.0 * p2 * x * y);\r\n\t}\r\n\t//Step 2 : ideal coordinates => actual coordinates \r\n\t{\r\n\t\txCorrected = xCorrected * fx + ux;\r\n\t\tyCorrected = yCorrected * fy + uy;\r\n\t}\r\n\tpoint = vec2 (xCorrected, yCorrected);\r\n\r\n\treturn point;\r\n}\r\n\r\nvec2 undistort(vec2 pt) {\r\n\tfloat fx = CameraIntrinsicMatrix[0];\r\n\tfloat fy = CameraIntrinsicMatrix[4];\r\n\tfloat ifx = 1.0 / fx;\r\n\tfloat ify = 1.0 / fy;\r\n\tfloat cx = CameraIntrinsicMatrix[2];\r\n\tfloat cy = CameraIntrinsicMatrix[5];\r\n\r\n\tfloat x;\r\n\tfloat y;\r\n\tfloat x0 = 0.0;\r\n\tfloat y0 = 0.0;\r\n\tfloat u;\r\n\tfloat v;\r\n\r\n\tvec2 ret;\r\n\r\n\tx = pt.x;\r\n\ty = pt.y;\r\n\r\n\tu = x;\r\n\tv = y;\r\n\tx = (x - cx) * ifx;\r\n\ty = (y - cy) * ify;\r\n\r\n\tx0 = x;\r\n\ty0 = y;\r\n\r\n\tfloat k[14];\r\n\tfor (int i = 0; i < 14; i++)\r\n\t{\r\n\t\tk[i] = 0.0;\r\n\t}\r\n\tfor (int i = 0; i < 5; i++)\r\n\t{\r\n\t\tk[i] = CameraDistortionCoefficient[i];\r\n\t}\r\n\r\n\tfor (int j = 0; j < 5; j++)\r\n\t{\r\n\t\tfloat r2 = x * x + y * y;\r\n\t\tfloat icdist = (1.0 + ((k[7] * r2 + k[6]) * r2 + k[5]) * r2) / (1.0 + ((k[4] * r2 + k[1]) * r2 + k[0]) * r2);\r\n\t\tfloat deltaX = 2.0 * k[2] * x * y + k[3] * (r2 + 2.0 * x * x) + k[8] * r2 + k[9] * r2 * r2;\r\n\t\tfloat deltaY = k[2] * (r2 + 2.0 * y * y) + 2.0 * k[3] * x * y + k[10] * r2 + k[11] * r2 * r2;\r\n\t\tx = (x0 - deltaX) * icdist;\r\n\t\ty = (y0 - deltaY) * icdist;\r\n\t}\r\n\r\n\tfloat xx = CameraIntrinsicMatrix[0] * x + CameraIntrinsicMatrix[1] * y + CameraIntrinsicMatrix[2];\r\n\tfloat yy = CameraIntrinsicMatrix[3] * x + CameraIntrinsicMatrix[4] * y + CameraIntrinsicMatrix[5];\r\n\tfloat ww = 1.0 / (CameraIntrinsicMatrix[6] * x + CameraIntrinsicMatrix[7] * y + CameraIntrinsicMatrix[8]);\r\n\tx = xx * ww;\r\n\ty = yy * ww;\r\n\r\n\tret.x = x;\r\n\tret.y = y;\r\n\treturn ret;\r\n}\r\n\r\nvoid main()\r\n{\r\n\tvec2 fragCoord = gl_FragCoord.xy;\r\n\tfragCoord.y = float(ScreenHeight) - fragCoord.y; //Y\u8ef8\u7ffb\u8f49\r\n\r\n\tvec2 point = vec2(fragCoord.x * (CameraWidth / float(ScreenWidth)), fragCoord.y * (CameraHeight / float(ScreenHeight)));\r\n\tvec2 tp = point;\r\n\r\n\t//distort->\u53d6\u5f97undistort\u5f8ctp\u756b\u5728\u539f\u4f4d\u7f6e\u4e0a\uff0c\u53cd\u4e4b\u4ea6\u7136\r\n\tif (EnableDistort) {\r\n\t\ttp = undistort(tp);\r\n\t}\r\n\t\r\n\tif (EnableUndistort) {\r\n\t\ttp = distort(tp);\r\n\t}\r\n\r\n\ttp.x /= CameraWidth;\r\n\ttp.y /= CameraHeight;\r\n\r\n\tif (tp.x > 1.0 || tp.x < 0.0 || tp.y > 1.0 || tp.y < 0.0) {\r\n\t\tdiscard;\r\n\t}\r\n\tvec4 color = texture2D(ImageSource, tp);\r\n\r\n\tgl_FragColor = color;\r\n}\r\n';
