	e[0] = b1.x / b1Len; e[4] = b1.y / b1Len; e[8] = b1.z / b1Len; e[12] = 0;
	e[1] = b2.x / b2Len; e[5] = b2.y / b2Len; e[9] = b2.z / b2Len; e[13] = 0;
	e[2] = b3.x / b3Len; e[6] = b3.y / b3Len; e[10] = b3.z / b3Len; e[14] = 0;
