		aaBox.Min.y = node.Leaves[i].AABox.Min.y;
		aaBox.Min.z = node.Leaves[i].AABox.Min.z;
		aaBox.Max.x = node.Leaves[i].AABox.Max.x;
		aaBox.Max.y = node.Leaves[i].AABox.Max.y;
